"""Next firing times of a five-field cron expression. See task.md."""

from __future__ import annotations

import re
from datetime import datetime, timedelta


class CronError(ValueError):
    """Raised for malformed expressions and for searches that find nothing."""


_MONTH_NAMES = {
    "JAN": 1, "FEB": 2, "MAR": 3, "APR": 4, "MAY": 5, "JUN": 6,
    "JUL": 7, "AUG": 8, "SEP": 9, "OCT": 10, "NOV": 11, "DEC": 12,
}

_DOW_NAMES = {
    "SUN": 0, "MON": 1, "TUE": 2, "WED": 3, "THU": 4, "FRI": 5, "SAT": 6,
}

_INT_RE = re.compile(r"\d+")


def _resolve_value(token: str, lo: int, hi: int, name_map: dict | None) -> int:
    if name_map is not None and token.upper() in name_map:
        return name_map[token.upper()]
    if not _INT_RE.fullmatch(token):
        raise CronError(f"invalid value: {token!r}")
    value = int(token)
    if value < lo or value > hi:
        raise CronError(f"value out of range: {token!r}")
    return value


def _parse_step(token: str) -> int:
    if not _INT_RE.fullmatch(token):
        raise CronError(f"invalid step: {token!r}")
    step = int(token)
    if step < 1:
        raise CronError(f"step must be >= 1: {token!r}")
    return step


def _parse_term(term: str, lo: int, hi: int, name_map: dict | None) -> set[int]:
    if term == "":
        raise CronError("empty term")

    if "/" in term:
        base, step_s = term.split("/", 1)
        step = _parse_step(step_s)
        if base == "*":
            start, end = lo, hi
        elif "-" in base:
            a_s, b_s = base.split("-", 1)
            start = _resolve_value(a_s, lo, hi, name_map)
            end = _resolve_value(b_s, lo, hi, name_map)
            if start > end:
                raise CronError(f"range low above high: {term!r}")
        else:
            start = _resolve_value(base, lo, hi, name_map)
            end = hi
        return set(range(start, end + 1, step))

    if term == "*":
        return set(range(lo, hi + 1))

    if "-" in term:
        a_s, b_s = term.split("-", 1)
        start = _resolve_value(a_s, lo, hi, name_map)
        end = _resolve_value(b_s, lo, hi, name_map)
        if start > end:
            raise CronError(f"range low above high: {term!r}")
        return set(range(start, end + 1))

    return {_resolve_value(term, lo, hi, name_map)}


def _parse_field(text: str, lo: int, hi: int, name_map: dict | None = None) -> tuple[set[int], bool]:
    restricted = text != "*"
    values: set[int] = set()
    for term in text.split(","):
        values |= _parse_term(term, lo, hi, name_map)
    return values, restricted


def _add_years(d, years: int):
    try:
        return d.replace(year=d.year + years)
    except ValueError:
        # Feb 29 with no corresponding day five years later.
        return d.replace(year=d.year + years, day=28)


def _day_matches(d, month_set, dom_set, dow_set, dom_restricted, dow_restricted) -> bool:
    if d.month not in month_set:
        return False
    dow = (d.weekday() + 1) % 7  # cron: Sunday=0 .. Saturday=6
    dom_match = d.day in dom_set
    dow_match = dow in dow_set
    if dom_restricted and dow_restricted:
        return dom_match or dow_match
    if dom_restricted:
        return dom_match
    if dow_restricted:
        return dow_match
    return True


def next_firings(expr: str, start: datetime, count: int) -> list[datetime]:
    """Return the next `count` firing times strictly after `start`."""
    if count == 0:
        return []

    fields = expr.split()
    if len(fields) != 5:
        raise CronError(f"expected 5 fields, got {len(fields)}")
    minute_f, hour_f, dom_f, month_f, dow_f = fields

    minute_set, _ = _parse_field(minute_f, 0, 59)
    hour_set, _ = _parse_field(hour_f, 0, 23)
    dom_set, dom_restricted = _parse_field(dom_f, 1, 31)
    month_set, _ = _parse_field(month_f, 1, 12, _MONTH_NAMES)
    dow_raw, dow_restricted = _parse_field(dow_f, 0, 7, _DOW_NAMES)
    dow_set = {0 if v == 7 else v for v in dow_raw}

    minutes_sorted = sorted(minute_set)
    hours_sorted = sorted(hour_set)

    first_candidate = start.replace(second=0, microsecond=0)
    if first_candidate <= start:
        first_candidate += timedelta(minutes=1)

    limit_date = _add_years(start.date(), 5)

    results: list[datetime] = []
    d = first_candidate.date()
    while d <= limit_date:
        if _day_matches(d, month_set, dom_set, dow_set, dom_restricted, dow_restricted):
            for h in hours_sorted:
                for m in minutes_sorted:
                    candidate = datetime(d.year, d.month, d.day, h, m)
                    if candidate > start:
                        results.append(candidate)
                        if len(results) == count:
                            return results
        d += timedelta(days=1)

    raise CronError("no firing within five years of start")
